import{$ as e,B as t,o as n,z as r}from"./chunks/framework.BROBN02c.js";var i=JSON.parse(`{"title":"内嵌镜像与键盘映射","description":"","frontmatter":{"title":"内嵌镜像与键盘映射"},"headers":[],"relativePath":"zhHans/guide/mirror.md","filePath":"zhHans/guide/mirror.md","lastUpdated":1795601116000}`),a={name:`zhHans/guide/mirror.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="内嵌镜像与键盘映射" tabindex="-1">内嵌镜像与键盘映射 <a class="header-anchor" href="#内嵌镜像与键盘映射" aria-label="Permalink to &quot;内嵌镜像与键盘映射&quot;">​</a></h1><p>内嵌镜像把手机画面直接渲染在 Escrcpy 自己的窗口里（而不是 scrcpy 的原生窗口），因此可以在画面上叠加键盘映射、窗口置顶、全屏等能力。视频由 WebCodecs 硬件解码，音频通过 Web Audio 播放。</p><h2 id="打开方式" tabindex="-1">打开方式 <a class="header-anchor" href="#打开方式" aria-label="Permalink to &quot;打开方式&quot;">​</a></h2><ol><li>在设备列表找到目标设备</li><li>点击设备行右侧的「更多」（＋）按钮</li><li>选择「内嵌镜像」</li></ol><p>镜像窗口会记住上次的位置和尺寸；标题栏依次是：设备名、分辨率、帧率、声音开关、键盘映射、置顶、全屏、关闭。</p><h2 id="输入" tabindex="-1">输入 <a class="header-anchor" href="#输入" aria-label="Permalink to &quot;输入&quot;">​</a></h2><ul><li><strong>鼠标 / 触摸</strong>：左键按下即触控，支持多指（指针分别映射为独立触点）</li><li><strong>滚轮</strong>：在画面上滚动；若启用了「滚动」键盘映射，则转换为双指捏合缩放</li><li><strong>键盘</strong>：物理按键映射为 Android 按键；中文、表情等字符直接以文本注入</li><li><strong>Esc</strong>：返回；剪贴板在窗口获得焦点时自动同步到设备</li><li><strong>右键</strong>：返回（编辑模式下右键用于添加映射）</li></ul><h2 id="键盘映射" tabindex="-1">键盘映射 <a class="header-anchor" href="#键盘映射" aria-label="Permalink to &quot;键盘映射&quot;">​</a></h2><p>点击标题栏的网格图标打开键盘映射面板，右侧面板顶部可切换三种模式：</p><table tabindex="0"><thead><tr><th>模式</th><th>说明</th></tr></thead><tbody><tr><td>映射关闭</td><td>不启用任何映射，仅保留普通触控</td></tr><tr><td>编辑模式</td><td>可右键画面添加映射、拖动节点、调整参数</td></tr><tr><td>使用模式</td><td>按下绑定的按键即触发对应触控</td></tr></tbody></table><h3 id="添加映射" tabindex="-1">添加映射 <a class="header-anchor" href="#添加映射" aria-label="Permalink to &quot;添加映射&quot;">​</a></h3><ol><li>切到「编辑模式」</li><li>在画面上右键 → 在该位置新增一个点击映射</li><li>选中映射，点击「绑定按键」，按下键盘组合（Esc 取消）</li><li>在下方选择映射类型并调整参数</li></ol><p>支持的映射类型：</p><ul><li><strong>点击</strong>：按键触发一次点击</li><li><strong>滑动</strong>：按键触发一次向上/下/左/右的滑动，可调距离与时长</li><li><strong>连点</strong>：按住按键按设定间隔连点</li><li><strong>滚动</strong>：鼠标滚轮转换为双指捏合缩放</li><li><strong>摇杆</strong>：WASD 四向绑定，按住方向键在半径内拖动，适合游戏虚拟摇杆</li><li><strong>视角控制</strong>：鼠标移动映射为视角滑动</li><li><strong>宏</strong>：按键运行一条已有的自动化工作流，可设置循环次数</li></ul><h3 id="方案管理" tabindex="-1">方案管理 <a class="header-anchor" href="#方案管理" aria-label="Permalink to &quot;方案管理&quot;">​</a></h3><p>映射按「方案」保存，每台设备独立。面板左上角可新建 / 复制 / 删除方案；「导入 / 导出」使用 JSON 文件，方便在多台电脑之间迁移。</p><h2 id="工作流可视化编辑器" tabindex="-1">工作流可视化编辑器 <a class="header-anchor" href="#工作流可视化编辑器" aria-label="Permalink to &quot;工作流可视化编辑器&quot;">​</a></h2><p>「自动任务 → 工作流 → 新建工作流」现在是一个节点画布：</p><ul><li>开始 → 各步骤 → 结束，自动连线</li><li>拖动节点调整位置；把节点拖到另一个节点上可插入到该顺序</li><li>工具栏支持缩放、适应画布、自动排列；Ctrl + 滚轮缩放，拖动空白处平移</li><li>右侧检查器直接编辑所选步骤（AI / 动作 / 延时）</li><li>快捷键：Delete 删除所选步骤，Ctrl + D 复制</li></ul><h2 id="网页版" tabindex="-1">网页版 <a class="header-anchor" href="#网页版" aria-label="Permalink to &quot;网页版&quot;">​</a></h2><p>开启网页版后，浏览器里新增「镜像」页签：选择设备 → 连接，画面通过 SSE 推送码流并由浏览器 WebCodecs 解码，支持触摸、键盘、滚轮、剪贴板与键盘映射（点击映射 + 按键绑定）。自动任务页同时展示工作流的可视化链路，可一键运行。</p>`,21)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};